"use strict";(globalThis.webpackChunkmobile=globalThis.webpackChunkmobile||[]).push([[7873],{6742(e,t,n){n.r(t),n.d(t,{assets:()=>l,contentTitle:()=>r,default:()=>h,frontMatter:()=>s,metadata:()=>o,toc:()=>c});const o=JSON.parse('{"id":"Jetpack Compose/Dynamic UI/Overlays & Polish/Dialog and AlertDialog","title":"06. Dialog and AlertDialog","description":"Welcome to the Path! Today we will tackle dialog windows (Dialog and AlertDialog)","source":"@site/docs/100. Jetpack Compose/20. Dynamic UI/50. Overlays & Polish/10.Dialog and AlertDialog.mdx","sourceDirName":"100. Jetpack Compose/20. Dynamic UI/50. Overlays & Polish","slug":"/Jetpack Compose/Dynamic UI/Overlays & Polish/Dialog and AlertDialog","permalink":"/mobile/docs/Jetpack Compose/Dynamic UI/Overlays & Polish/Dialog and AlertDialog","draft":false,"unlisted":false,"editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/docs/100. Jetpack Compose/20. Dynamic UI/50. Overlays & Polish/10.Dialog and AlertDialog.mdx","tags":[],"version":"current","sidebarPosition":10,"frontMatter":{"title":"06. Dialog and AlertDialog"},"sidebar":"tutorialSidebar","previous":{"title":"06. Toast & Snackbar","permalink":"/mobile/docs/Jetpack Compose/Dynamic UI/Scaffold & Notifications/SnackBar and Toast"},"next":{"title":"AnimatedVisibility","permalink":"/mobile/docs/Jetpack Compose/Dynamic UI/Overlays & Polish/AnimatedVisibility"}}');var a=n(4848),i=n(8453);const s={title:"06. Dialog and AlertDialog"},r="Dialog & AlertDialog w Jetpack Compose: Dylematy Wied\u017amina",l={},c=[{value:"1. Top-Down: Pe\u0142ny Kod Zlecenia",id:"1-top-down-pe\u0142ny-kod-zlecenia",level:2},{value:"Breakdown and Explanation (4W2H Data Logistics)",id:"breakdown-and-explanation-4w2h-data-logistics",level:2},{value:"Comparison: Compose vs. The Old XML World",id:"comparison-compose-vs-the-old-xml-world",level:2},{value:"Summary",id:"summary",level:2}];function d(e){const t={code:"code",h1:"h1",h2:"h2",header:"header",li:"li",ol:"ol",p:"p",pre:"pre",...(0,i.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.header,{children:(0,a.jsx)(t.h1,{id:"dialog--alertdialog-w-jetpack-compose-dylematy-wied\u017amina",children:"Dialog & AlertDialog w Jetpack Compose: Dylematy Wied\u017amina"})}),"\n",(0,a.jsx)(t.p,{children:"Welcome to the Path! Today we will tackle dialog windows (Dialog and AlertDialog)\nin Jetpack Compose. In the world of mobile applications, dialogs are decision-making\nmoments\u2014they resemble a situation where Geralt of Rivia stands before a notice board\nand has to make a choice: whether to accept a monster contract or haggle\nfor more orens."}),"\n",(0,a.jsx)(t.h2,{id:"1-top-down-pe\u0142ny-kod-zlecenia",children:"1. Top-Down: Pe\u0142ny Kod Zlecenia"}),"\n",(0,a.jsx)(t.p,{children:'Here is the working code for the notice board at the "Seven Cats Inn".\nWe have two types of dialogs here: the system AlertDialog for confirming the contract,\nand a custom Dialog for our own monster stats view.'}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-kotlin",children:'@Composable\nfun WitcherContractScreen() {\n    // Stan naszych dialog\xf3w\n    var showAcceptContract by remember { mutableStateOf(false) }\n    var showMonsterStats by remember { mutableStateOf(false) }\n\n    Column(\n        modifier = Modifier.fillMaxSize().padding(16.dp),\n        horizontalAlignment = Alignment.CenterHorizontally,\n        verticalArrangement = Arrangement.Center\n    ) {\n        Text("Zlecenie: Strzyga w Wyzimie", style = MaterialTheme.typography.headlineMedium)\n        Spacer(modifier = Modifier.height(32.dp))\n\n        Button(onClick = { showAcceptContract = true }) {\n            Text("Akceptuj Kontrakt")\n        }\n\n        Spacer(modifier = Modifier.height(16.dp))\n\n        Button(onClick = { showMonsterStats = true }) {\n            Text("Sprawd\u017a Bestiariusz (Strzyga)")\n        }\n    }\n\n    // 1. AlertDialog - Szybka decyzja systemowa\n    if (showAcceptContract) {\n        AlertDialog(\n            onDismissRequest = { showAcceptContract = false },\n            title = { Text(text = "Nowy Kontrakt") },\n            text = { Text(text = "Czy zgadzasz si\u0119 zabi\u0107 Strzyg\u0119 za 3000 oren\xf3w?") },\n            confirmButton = {\n                TextButton(\n                    onClick = {\n                        /* Logika przyj\u0119cia zlecenia */\n                        showAcceptContract = false\n                    }\n                ) {\n                    Text("Toss a coin (Bior\u0119)")\n                }\n            },\n            dismissButton = {\n                TextButton(onClick = { showAcceptContract = false }) {\n                    Text("Odrzu\u0107")\n                }\n            }\n        )\n    }\n\n    // 2. Custom Dialog - Pe\u0142na kontrola nad UI\n    if (showMonsterStats) {\n        Dialog(onDismissRequest = { showMonsterStats = false }) {\n            Card(\n                modifier = Modifier.fillMaxWidth().height(250.dp).padding(16.dp),\n                shape = MaterialTheme.shapes.medium,\n            ) {\n                Column(\n                    modifier = Modifier.fillMaxSize().padding(16.dp),\n                    horizontalAlignment = Alignment.CenterHorizontally\n                ) {\n                    Text("Statystyki: Strzyga", style = MaterialTheme.typography.titleLarge)\n                    Spacer(modifier = Modifier.height(16.dp))\n                    Text("S\u0142abo\u015bci: Srebrny miecz, Znak Yrden")\n                    Spacer(modifier = Modifier.weight(1f))\n                    Button(onClick = { showMonsterStats = false }) {\n                        Text("Zamknij Bestiariusz")\n                    }\n                }\n            }\n        }\n    }\n}\n'})}),"\n",(0,a.jsxs)(t.p,{children:[":::question Pytanie do przemy\u015blenia \ud83e\udde0:\nJak to si\u0119 dzieje, \u017ce Geralt widzi na ekranie nowe okno zlecenia,\nskoro w kodzie nie ma ani jednej linijki typu ",(0,a.jsx)(t.code,{children:"dialog.show()"}),"?"]}),"\n",(0,a.jsx)(t.h2,{id:"breakdown-and-explanation-4w2h-data-logistics",children:"Breakdown and Explanation (4W2H Data Logistics)"}),"\n",(0,a.jsx)(t.p,{children:"To understand this mechanism, let's look at how a massive restaurant or a logistics center operates. In programming, we must answer 6 fundamental questions, known as the 4W2H model: What?, Where?, When?, Who?, How?, and How Long? Here is how the model relates to our Dialogs:"}),"\n",(0,a.jsxs)(t.ol,{start:"0",children:["\n",(0,a.jsxs)(t.li,{children:["\n",(0,a.jsx)(t.p,{children:'WHAT (What controls the dialog?)\nThe Sticky Note (Primitives): The showAcceptContract variable is a short, simple piece of information, e.g., true/false. It is fleeting and easy to handle. In Jetpack Compose, it is precisely this simplest state (primitive) that acts as the "remote control" turning our dialog on or off on the screen.'}),"\n"]}),"\n",(0,a.jsxs)(t.li,{children:["\n",(0,a.jsx)(t.p,{children:"WHERE (Where do we store the information about opening the window?)\nThe Pocket (Local Variables): Our state lives directly inside the @Composable function. The chef keeps the recipe in their apron pocket. Only they have access to it, and the data disappears when their shift ends."}),"\n"]}),"\n",(0,a.jsxs)(t.li,{children:["\n",(0,a.jsx)(t.p,{children:'WHEN (When does the application draw the Dialog on the screen?)\nThe Lazy Paradigm (The Drive-Thru): The code in the if (showAcceptContract) block waits for our command. The computer does nothing until the application explicitly asks for the next element. When the user clicks the "Accept" button, the chef fries exactly one burger\u2014meaning Compose calculates and draws the AlertDialog strictly on demand.'}),"\n"]}),"\n",(0,a.jsxs)(t.li,{children:["\n",(0,a.jsx)(t.p,{children:'WHO (Who orders the window to open?)\nPush Model (The Sushi Conveyor Belt): Here, we react to asynchronous user events. The application sets up a "listener" and waits asynchronously. That mouse or finger click is the moment when the external world "pushes" new information whenever it wants, forcing the interface to show the contract.'}),"\n"]}),"\n",(0,a.jsxs)(t.li,{children:["\n",(0,a.jsx)(t.p,{children:"HOW (How does the interface know we changed the state?)\nThe PA System (State / Public Address System): The application's interface instantly, automatically, and independently replaces the item on the screens. Thanks to using mutableStateOf, Compose acts like a chef shouting through a loudspeaker. When you set the state to false, the window will disappear from the screen."}),"\n"]}),"\n",(0,a.jsxs)(t.li,{children:["\n",(0,a.jsx)(t.p,{children:"HOW LONG (How long will we remember this window?)\nShort-term Memory (Volatile memory): Our dialog state lives only as long as the screen. Rotating the phone screen (or restarting the application) is like a waiter tripping\u2014the data is lost forever. If you rotate the phone, the open dialog for the Striga contract will be reset."}),"\n"]}),"\n"]}),"\n",(0,a.jsx)(t.h2,{id:"comparison-compose-vs-the-old-xml-world",children:"Comparison: Compose vs. The Old XML World"}),"\n",(0,a.jsx)(t.p,{children:"Let's look at the evolution of solutions. Do you remember how Geralt had to look for a campfire in the first parts of the game to meditate and consume potions? Creating dialogs in the old XML system was similarly exhausting."}),"\n",(0,a.jsx)(t.p,{children:"Kotlin + XML (Imperative): You had to use an instance of AlertDialog.Builder. The commands were imperative: create an object, add a title to it, set listeners for onClick, and then manually tell it to show by calling dialog.show(). When you wanted to close it, you had to keep a reference to it to use dialog.dismiss(). Forgetting to close the dialog before the screen was destroyed caused the famous WindowLeaked error."}),"\n",(0,a.jsx)(t.p,{children:"Jetpack Compose (Declarative): You simply declare what should happen under given conditions. if (showDialog) then turn it on, when false turn it off. Compose manages the removal of the window itself, taking the risk of memory leaks off your shoulders."}),"\n",(0,a.jsx)(t.h2,{id:"summary",children:"Summary"}),"\n",(0,a.jsx)(t.p,{children:'In Jetpack Compose, we have two basic overlay windows: AlertDialog, dedicated to quick, system-level questions ("Yes/No") with an imposed structure (Title, Text, ConfirmButton), and the base, pure Dialog, inside of which you can create any UI just like on a blank canvas. The logistics of rendering them always comes down to managing a simple Boolean logic state.'}),"\n",(0,a.jsx)(t.p,{children:"Test your knowledge:"}),"\n",(0,a.jsx)(t.p,{children:'Which of the paradigms ("Eager" or "Lazy") best describes how Compose decides when to render the AlertDialog component on the screen?'}),"\n",(0,a.jsx)(t.p,{children:"What are the main differences in configuration parameters between AlertDialog and the standard Dialog?"}),"\n",(0,a.jsx)(t.p,{children:"What will happen to the open Striga contract window if our state is controlled only by a basic remember, and the user suddenly rotates their phone screen, and why does this happen?"})]})}function h(e={}){const{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(d,{...e})}):d(e)}},8453(e,t,n){n.d(t,{R:()=>s,x:()=>r});var o=n(6540);const a={},i=o.createContext(a);function s(e){const t=o.useContext(i);return o.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:s(e.components),o.createElement(i.Provider,{value:t},e.children)}}}]);